import React, { memo, useEffect, useCallback } from 'react';
import { toast } from 'react-hot-toast';
import ChatPanel from '../../components/chat/ChatPanel';
import CommonAdsSection from '../../components/CommonAdsSection';

const CONSULTANT_PUBLIC_CONVERSATION_ID = 2;
const COMPLETED_CONSULTATION_STORAGE_KEY =
  'completedConsultationConversationIds';

const ConsultantChatPage = memo(() => {
  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'auto' });
  }, []);

  const handleMarkAsComplete = useCallback((conversationId) => {
    try {
      const saved = localStorage.getItem(COMPLETED_CONSULTATION_STORAGE_KEY);
      const ids = saved ? JSON.parse(saved) : [];
      const next = Array.from(new Set([...ids, conversationId]));
      localStorage.setItem(
        COMPLETED_CONSULTATION_STORAGE_KEY,
        JSON.stringify(next),
      );
    } catch {
      // Storage errors should not block chat actions.
    }
    toast.success('Session marked as complete!');
  }, []);

  return (
    <div className='bg-gray-50'>
      <div className='container mx-auto px-4 lg:px-6 pt-6 pb-12'>
        <div className='h-[70vh] min-h-130'>
          <ChatPanel
            className='h-full'
            showConversations={false}
            showMarkAsComplete
            activeConversationId={CONSULTANT_PUBLIC_CONVERSATION_ID}
            onMarkAsComplete={handleMarkAsComplete}
          />
        </div>
      </div>
      <div className='pb-12'>
        <CommonAdsSection
          containerClassName='container mx-auto px-4 lg:px-6'
        />
      </div>
    </div>
  );
});

ConsultantChatPage.displayName = 'ConsultantChatPage';

export default ConsultantChatPage;
